or:pointer}.ck-item b{display:block;font-size:12px;line-height:1.5}.ck-item small{display:block;color:var(--muted);font-size:11px;line-height:1.55;margin-top:3px}.ck-item:has(input:checked){background:#EEF7FB;border-color:#B8D5E3}.ck-item:has(input:checked) b{text-decoration:line-through;color:#527B91}.ck-modal-note{font-size:11px;color:#5C748A;line-height:1.65;margin:19px 0 0;padding:12px;background:#F3F7FA;border-radius:9px}.ck-dialog-foot{border-top:1px solid #E7EFF4;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 29px;background:#fff}.ck-saved{color:var(--muted);font-size:11px}.ck-done{border:0;background:var(--teal);color:#fff;border-radius:9px;padding:11px 22px;font-size:12px;font-weight:800;transition:.25s}.ck-done:hover{background:#185877;transform:translateY(-2px)}@keyframes ck-in{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}@media(max-width:700px){.ck-hero{grid-template-columns:1fr;padding:24px}.ck-total{justify-content:start}.ck-top{align-items:start}.ck-dialog-head,.ck-dialog-scroll,.ck-dialog-foot{padding-left:19px;padding-right:19px}}@media(prefers-reduced-motion:reduce){.ck-card,.ck-dialog{animation:none;transition:none}}
