@push('scripts')
<script>
(() => {
'use strict';
// Sample data. Later, replace this list with scholarships tracked by the authenticated user.
const scholarships = [
 {id:'dost-sei',title:'DOST-SEI Undergraduate Scholarship',provider:'Department of Science and Technology',category:'STEM / Government',deadline:'Check official announcement',requirements:[['Completed application form','Fill out the official provider application form.'],['Recent ID photograph','Prepare a clear, recent photo.'],['Birth certificate','Prepare a readable copy.'],['Certified school grades','Request an official report of grades.'],['Enrollment or admission document','Prepare proof of enrollment or admission.'],['Household income document','Confirm which proof the provider accepts.']]},
 {id:'ched-merit',title:'CHED Merit Scholarship Program',provider:'Commission on Higher Education',category:'Academic Merit',deadline:'Check official announcement',requirements:[['Application form','Complete the provider application form.'],['Recent ID photo','Prepare an identification photograph.'],['Academic records','Secure your latest certified grades.'],['Proof of enrollment','Prepare a certificate or admission confirmation.'],['Proof of citizenship','Prepare the applicable government document.'],['Income-related document','Check which documents are accepted.']]},
 {id:'sm-foundation',title:'SM Foundation College Scholarship',provider:'SM Foundation',category:'Private Foundation',deadline:'Check official announcement',requirements:[['Online application form','Complete the official form.'],['Latest report card','Prepare a clear copy of your grades.'],['School registration document','Prepare current or incoming enrollment details.'],['Valid identification','Prepare an accepted ID.'],['Family income document','Check the provider instructions.']]},
 {id:'city-grant',title:'Local Government Educational Assistance',provider:'Sample City Scholarship Office',category:'Local / Government',deadline:'Check local office',requirements:[['Application form','Obtain the local scholarship form.'],['Proof of residency','Prepare a barangay certificate or accepted alternative.'],['School registration','Prepare a certificate of enrollment.'],['Latest grades','Prepare your report card or transcript.'],['Valid ID','Check accepted IDs with the provider.']]},
 {id:'academic-excellence',title:'University Academic Excellence Grant',provider:'Sample University Financial Aid Office',category:'University-Based',deadline:'Check school announcement',requirements:[['Scholarship request form','Complete the official institution form.'],['Certificate of enrollment','Request an updated certificate.'],['Certified grades','Secure your academic record.'],['Letter of intent','Write a short statement about your goals.'],['Student ID','Prepare a copy of your university ID.']]}
];
const $ = id => document.getElementById(id);
const escapeHtml = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Demo browser persistence, scoped by logged-in user when available.
const key = 'scholarhunt-demo-checklist-{{ auth()->id() ?? "guest" }}';
let saved = {};try {saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch(_){saved={};}
const checked = s => new Set(Array.isArray(saved[s.id])?saved[s.id]:[]);
const count = s => checked(s).size;
const percent = s => Math.round(count(s)/s.requirements.length*100);
let current=null, previousFocus=null;
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));$('ck-saved').textContent='Progress saved on this browser';}catch(_){$('ck-saved').textContent='Storage unavailable; changes last only this session';}}
function render(){
 const q=$('ck-search').value.toLowerCase().trim();const visible=scholarships.filter(s=>[s.title,s.provider,s.category].join(' ').toLowerCase().includes(q));
 $('ck-grid').innerHTML=visible.map(s=>`<button class="ck-card" type="button" data-id="${escapeHtml(s.id)}"><div class="ck-card-top"><span class="ck-category">${escapeHtml(s.category)}</span><span class="ck-count">${count(s)} / ${s.requirements.length} ready</span></div><h3>${escapeHtml(s.title)}</h3><p class="ck-provider">${escapeHtml(s.provider)}</p><p class="ck-deadline">◷ ${escapeHtml(s.deadline)}</p><div class="ck-progress-row"><span>Preparation progress</span><strong>${percent(s)}%</strong></div><div class="ck-track"><span style="width:${percent(s)}%"></span></div><div class="ck-open"><span>Open requirements</span><span>→</span></div></button>`).join('');
 $('ck-empty').classList.toggle('show',!visible.length);$('ck-scholarship-count').textContent=scholarships.length;$('ck-finished-count').textContent=scholarships.filter(s=>percent(s)===100).length;
}
function modalProgress(){const done=count(current),total=current.requirements.length;$('ck-modal-count').textContent=`${done} of ${total} prepared`;$('ck-modal-percent').textContent=percent(current)+'%';$('ck-modal-bar').style.width=percent(current)+'%';}
function open(id){const found=scholarships.find(s=>s.id===id);if(!found)return;current=found;previousFocus=document.activeElement;$('ck-dialog-title').textContent=found.title;$('ck-dialog-provider').textContent=found.provider;const items=checked(found);$('ck-items').innerHTML=found.requirements.map(([name,hint],i)=>`<label class="ck-item"><input type="checkbox" data-index="${i}" ${items.has(i)?'checked':''}><span><b>${escapeHtml(name)}</b><small>${escapeHtml(hint)}</small></span></label>`).join('');modalProgress();$('ck-overlay').classList.add('open');$('ck-overlay').setAttribute('aria-hidden','false');document.body.style.overflow='hidden';$('ck-close').focus();}
function close(){$('ck-overlay').classList.remove('open');$('ck-overlay').setAttribute('aria-hidden','true');document.body.style.overflow='';current=null;previousFocus?.focus();}
$('ck-grid').addEventListener('click',e=>{const card=e.target.closest('[data-id]');if(card)open(card.dataset.id);});
$('ck-search').addEventListener('input',render);
$('ck-items').addEventListener('change',e=>{if(!current||!e.target.matches('input[type="checkbox"]'))return;const set=checked(current),i=Number(e.target.dataset.index);e.target.checked?set.add(i):set.delete(i);saved[current.id]=[...set];persist();modalProgress();render();});
$('ck-close').addEventListener('click',close);$('ck-done').addEventListener('click',close);$('ck-overlay').addEventListener('click',e=>{if(e.target===$('ck-overlay'))close();});
document.addEventListener('keydown',e=>{if(!$('ck-overlay').classList.contains('open'))return;if(e.key==='Escape'){close();return;}if(e.key==='Tab'){const focusable=[...$('ck-dialog').querySelectorAll('button:not([disabled]),input:not([disabled])')];const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
render();
})();
</script>
@endpush
